#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long i64;

int main() {
    size_t n;
    cin >> n;
    vector<i64> c(n), w(n);
    vector<i64> sum(n + 1, 0);
    vector<i64> dp(n + 1, 1e9); // Space optimization to 1D array

    for(size_t i = 0; i < n; ++i) {
        cin >> c[i] >> w[i];
        sum[i + 1] = sum[i] + w[i]; // Cumulative sum
    }

    dp[0] = 0; // Base case

    for(size_t l = 0; l < n; ++l) {
        i64 w_s_left = 0;
        for(size_t r = l + 1; r <= n; ++r) {
            w_s_left += w[r - 1]; // Update weights cumulatively
            if(c[l] >= w_s_left) {
                dp[r] = min(dp[r], 1LL); // Set to 1 if condition met
            }

            i64 w_s_right = sum[r - 1] - sum[l]; // Calculate remaining weight
            if(c[r - 1] >= w_s_right) {
                dp[r] = min(dp[r], 1LL); // Set to 1 if condition met
            }
        }
    }

    cout << dp[n] << endl; // Output the result for the entire array
}

