#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long i64;

struct ProblemData {
    vector<i64> capacities, weights, cumulative_sum;
};

int main() {
    size_t n;
    cin >> n;
    ProblemData data;
    data.capacities.resize(n);
    data.weights.resize(n);
    data.cumulative_sum.resize(n + 1);
    vector<i64> dp(n + 1, 1e9); // Space optimization to 1D array

    for(size_t i = 0; i < n; ++i) {
        cin >> data.capacities[i] >> data.weights[i];
        data.cumulative_sum[i + 1] = data.cumulative_sum[i] + data.weights[i];
    }

    dp[0] = 0; // Base case

    for(size_t l = 0; l < n; ++l) {
        // Instead of iterating through every r, we can find the maximum r that can fit
        for(size_t r = l + 1; r <= n; ++r) {
            i64 left_weight = data.cumulative_sum[r] - data.cumulative_sum[l + 1];
            if(data.capacities[l] >= left_weight) {
                dp[r] = min(dp[r], 1LL);
            }

            // Early exit if capacity check fails
            if(data.capacities[r - 1] < left_weight) {
                break;
            }

            i64 right_weight = data.cumulative_sum[r - 1] - data.cumulative_sum[l];
            if(data.capacities[r - 1] >= right_weight) {
                dp[r] = min(dp[r], 1LL);
            }
        }
    }

    cout << dp[n] << endl; // Output the result for the entire array
}

